--
-- Структура таблицы `easter`
--

CREATE TABLE `easter` (
  `id_easter` int NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `description` text,
  `media` text
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Дамп данных таблицы `easter`
--

INSERT INTO `easter` (`id_easter`, `name`, `description`, `media`) VALUES
(1, 'Zeri и Neon', 'В 2022 году Riot Games удивили сообщество, выпустив двух визуально похожих персонажей почти одновременно. В League of Legends появилась Zeri — девушка из Зауна со способностью накапливать статический заряд. А в Valorant — Neon из Филиппин, чьи электромагнитные способности позволяют ей развивать суперскорость. У обеих — короткие яркие волосы, азиатские черты лица и дерзкий, энергичный стиль. Разработчики официально объяснили это совпадением творческих замыслов: образ «дерзкой девчонки-молнии» просто оказался в тренде.', 'Zeri_and_Neon.png'),
(2, 'Назад в будущее', 'Карта Split известна не только своей вертикальной планировкой и японскими мотивами, но и скрытыми пасхалками. Самая заметная из них находится за пределами игровой зоны, рядом с точкой старта атакующей стороны. Там стоит автомобиль, который невозможно спутать ни с чем другим — серебристый DeLorean DMC-12 с характерными «крыльями чайки». Разработчики из Riot Games оставили эту машину как дань уважения фильму «Назад в будущее» (1985).', 'CarFilm.png');

