--
-- Структура таблицы `maps`
--

CREATE TABLE `maps` (
  `id` int NOT NULL,
  `name` varchar(50) NOT NULL,
  `release_date` varchar(50) DEFAULT NULL,
  `location` varchar(255) NOT NULL,
  `coordinates` varchar(150) DEFAULT NULL,
  `description` text
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Дамп данных таблицы `maps`
--

INSERT INTO `maps` (`id`, `name`, `release_date`, `location`, `coordinates`, `description`) VALUES
(1, 'ABYSS', 'июнь 2024', 'Сёр-Ян, Ян-Майен, Норвегия, Альфа-Земля', NULL, 'Всмотритесь в Бездну: Abyss – это секретная база, скрытая в глубине недоступной и бездонной пропасти. Используйте устройства по-новому, чтобы сбросить противников в пропасть или заставить их рисковать. Большой риск – залог больших наград, если вы исполните все безупречно.'),
(2, 'ASCENT', 'июнь 2020', 'Венеция, Италия, Альфа Земля', NULL, 'Открытая площадка для небольших позиционных боев на истощение разделяет две площадки на подъеме. Каждая площадка может быть укреплена необратимыми бомбовыми воротами; как только они будут опущены, вам придется уничтожить их или найти другой способ. Уступайте как можно меньше территории.'),
(3, 'BIND', 'апрель 2020 (бета)', 'Рабат, Марокко, Альфа Земля', NULL, 'Два места. Середины нет. Нужно выбрать левое или правое. Что же тогда будет? Оба предлагают атакующим прямые пути, а пара односторонних телепортов облегчает обход с фланга.'),
(4, 'BREEZE', 'апрель 2021', 'Бермудский треугольник, Атлантический океан, Альфа Земля', NULL, 'Полюбуйтесь историческими руинами или приморскими пещерами в этом тропическом раю. Но захватите с собой какое-нибудь укрытие. Оно понадобится вам на широких открытых пространствах и в дальних боях. Следите за своими флангами, и это не составит труда.'),
(5, 'CORRODE', 'июнь 2025', 'Мон-Сен-Мишель, Франция, Омега Земля', NULL, 'Французский город-крепость превратился в предприятие по добыче радианитовой соли. Прокладывайте себе путь по средневековым улицам, используя перепрофилированную промышленную технику, чтобы прорваться через многоуровневую оборону на этой традиционной карте с тремя полосами движения.'),
(6, 'FRACTURE', 'сентябрь 2021', 'Округ Санта-Фе, штат Нью-Мексико, США, Альфа Земля', NULL, 'Сверхсекретный исследовательский центр, разрушенный в результате неудачного эксперимента с радианитом. Возможности защиты разделены так же, как и карта, и выбор за вами: встретить нападающих на их территории или задраить люки, чтобы выдержать атаку.'),
(7, 'HAVEN', 'апрель 2020 (бета)', 'Тхимпху, Бутан, Альфа Земля', NULL, 'Под заброшенным монастырем поднимается шум из-за того, что конкурирующие агенты борются за контроль над тремя объектами. Здесь больше территории, которую нужно контролировать, но защитники могут использовать дополнительную недвижимость для агрессивных действий'),
(8, 'ICEBOX', 'октябрь 2020', 'Остров Беннетт, Россия, Альфа Земля', NULL, 'Вашим следующим полем битвы станут раскопки в секретном королевстве, затерянном в Арктике. Два завода, защищенные снегом и металлом, требуют некоторой горизонтальной аккуратности. Воспользуйтесь зиплайнами, и они вас не заметят.'),
(9, 'LOTUS', 'январь 2023', 'Западные Гаты, Индия, Омега Земля', NULL, 'Таинственное сооружение, в котором находится астральный канал, излучает древнюю силу. Огромные каменные двери открывают множество возможностей для передвижения и открывают пути к трем таинственным местам.'),
(10, 'PEARL', 'июнь 2022', 'Лиссабон, Португалия, Омега Земля', NULL, 'Атакующие атакуют обороняющихся на этой карте, состоящей из двух частей, действие которой разворачивается в оживленном подводном городе. Pearl - это карта, ориентированная на географию, без механики. Сражайтесь на компактных средних или дальнобойных флангах на нашей первой карте, созданной в Omega Earth.'),
(11, 'SPLIT', 'апрель 2020 (бета)', 'Токио, Япония, Альфа Земля', NULL, 'Если вы хотите забраться далеко, вам придется подняться наверх. Пара площадок, разделенных посередине возвышением, позволяет быстро передвигаться с помощью двух веревочных подъемников. На каждой площадке есть возвышающаяся башня, которая необходима для контроля. Не забудьте посмотреть сверху, пока все не взлетело до небес.'),
(12, 'SUNSET', 'август 2023', 'Лос-Анджелес, Калифорния, США, Альфа Земля', NULL, 'Катастрофа на местном предприятии kingdom угрожает охватить весь район. Остановитесь у своего любимого фургона с едой, а затем отправляйтесь в путь по городу на этой традиционной карте с тремя полосами движения.');

