--
-- Структура таблицы `paragraphs`
--

CREATE TABLE `paragraphs` (
  `id_par` int NOT NULL,
  `id_ep` int NOT NULL,
  `text` text NOT NULL,
  `media_type` enum('none','image','video') DEFAULT 'none',
  `media_url` varchar(500) DEFAULT NULL,
  `media_alt` varchar(500) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Дамп данных таблицы `paragraphs`
--

INSERT INTO `paragraphs` (`id_par`, `id_ep`, `text`, `media_type`, `media_url`, `media_alt`) VALUES
(1, 1, 'Все началось с Первой Вспышки, которая произошла в 2039 году. Это событие ознаменовало появление радианита – нового источника энергии, который человечество начало активно использовать. С появлением радианита в нашем мире возникли и радианты. Эти уникальные личности делятся на две категории: те, чье тело содержит радианит, благодаря чему у них проявились способности после Первой Вспышки, и те, кто научился использовать эти способности иным образом. В мире VALORANT существует компания под названием Kingdom, которая первой занялась сбором и исследованием радианита. После проведения многочисленных исследований было принято решение создать отряд под названием «Протокол VALORANT». Каждый радиант, вступающий в этот секретный отряд, обязан хранить информацию под строжайшим секретом, что означает прощание с обычной жизнью. У каждого агента есть своя мотивация для такого выбора.', 'none', NULL, NULL),
(2, 2, 'История VALORANT начинается с первого столкновения в 2049 году, произошедшего в Венеции между Jett и Phoenix. Несмотря на то, что оба являются членами одной команды, причина их конфликта связана с загадочной концепцией зеркального мира. Этот альтернативный мир населён теми же агентами, но с враждебными намерениями – они стремятся похитить радианит, используя специальное устройство под названием «Спайк», предназначенное для его поглощения. Параллельная планета, откуда прибывают зеркальные радианты, известна как планета Омега.', 'video', 'video/Episod01-04.mp4', 'Столкновение Phoenix и Jett'),
(3, 2, 'В результате Венеция «взлетает» (карта Ascent). Это событие широко освещается в новостях. На следующий день происходит еще одна атака в Марокко (карта Bind), но её успешно отражают Phoenix, Viper и Killjoy, причем Killjoy изобретает дефузер. Причина конфликта — загадочная концепция зеркального мира (планета Омега), населённая теми же агентами, но с враждебными намерениями: они стремятся похитить радианит из-за истощения собственных запасов.', 'video', 'video/РАЗДВОЕНИЕ.mp4', 'Агенты узнают о своих клонах'),
(4, 2, 'Сюжет получает развитие на карте Fracture, где раскрываются последствия неудачного эксперимента компании Kingdom на планетах Альфа и Омега. Разлом разделяет карту на пустынный сектор Омега (где радианит изучали интенсивнее, но он менее стабилен и опасен) и плодородный сектор Альфа.', 'none', NULL, NULL),
(5, 2, 'Chamber становится первым агентом, который устанавливает контакт со своим зеркальным двойником. Вместе они организуют саботаж, взрывая радианитовый суперколлайдер в лаборатории Эверетт-Линд, что приводит к полному разрыву отношений между двумя Землями. После этого Viper с нашей планеты обнаруживает портал Омега и поручает Killjoy его изучение для разработки аналогичного устройства.', NULL, NULL, NULL),
(6, 3, 'Для обеспечения необходимого количества энергии было решено привлечь Neon. Однако исследования могли бы зайти в тупик, если бы Chamber не предоставил Killjoy правильные чертежи межпространственного портала. Пока Killjoy и Neon работали над порталом, агент Yoru отправился на объект S22 для изучения разрушенного военного корабля. В ходе исследования были обнаружены пространственные рубцы, а на маске Yoru найдены частицы радианита, что указывает на то, что радианит существовал всегда, а его количество возросло после Первой вспышки. Во время попытки исследовать межпространственные швы Yoru провалился в прошлое, где кто-то звал его, но он не смог ответить. Параллельно с работами над порталом в сети начала распространяться информация о Jett и Phoenix, что вызвало вопросы у сотрудников семей Эверетт-Линд.', 'none', NULL, NULL),
(7, 3, 'Brimstone принял решение остановить работу над порталом и сосредоточиться на поисках шантажиста, который располагал досье на каждого агента «Протокола VALORANT». В ходе расследования выяснилось, что шантажистом оказалась Fade, которая мстила протоколу за потерю близкого человека. Однако после допроса Сайфера стало ясно, что к этому причастны агенты с Омеги. Сайфер предложил Brimstone использовать помощь Fade, поскольку она действовала из неведения и, по сути, могла перейти на их сторону. Бримстоун предложил ей вступить в протокол, и Fade согласилась, став 20-агентом. После урегулирования ситуации с шантажисткой работа над порталом возобновилась с целью вернуть похищенный радианит.', 'video', 'video/КОШМАРНЫХ СНОВ трейлер агента Fade.mp4', 'Захват шантажиста'),
(8, 3, 'После урегулирования ситуации работа над порталом возобновилась. Первый проход (Fade) оказался успешным. Второй переход совершила команда в составе Killjoy, Reyna и Neon. Они попали в Лиссабон на Земле Омега, где обнаружили, что похищенный радианит используется не для оружия, а для системы жизнеобеспечения под куполом Pearl (подводный город), поскольку на Омеге изменение климата вышло из-под контроля и большинство живёт в биокуполах.', 'video', 'video/ОСОЗНАНИЕ Официальный ролик к запуску эпизода 5.mp4', 'Первое ознакомление с Омега Землёй'),
(9, 4, 'Cypher получает информацию о том, что Омега получила доступ к могущественной силе, что может угрожать Альфе. В связи с этим протокол принимает в команду важного агента Harbor. Выясняется, что Valorant Legion (версия Протокола на Омеге) заинтересована в артефакте — браслете Harbor. Его подставила организация REALM, и он находится в бегах.', 'none', NULL, NULL),
(10, 4, 'Harbor и Astra отправляются на Омега-Землю в Город Цветов (карта Lotus), который построен космической расой Хранителей. Если Город Цветов на Омеге будет активирован, он уничтожит Землю Альфа. В ходе столкновения Омега-Astra активирует нексус, но команде Альфы удаётся установить Спайк, который поглощает большую часть энергии, предотвращая катастрофу.', 'video', 'video/Город цветов официальный трейлер карты Lotus.mp4', 'Город Цветов'),
(11, 5, 'В это время учёные из корпорации Kingdom приступили к экспериментам над животными, создавая существ, усиленных радианитом (радиворы). Протокол пригласил таких агентов, как Gekko (который скрывался от Kingdom после спасения радиворов-приятелей) и Deadlock. Deadlock и её команда столкнулись с медведем-радивором в Норвегии: зверь оторвал ей руки и убил отряд, после чего Killjoy создала протез. Deadlock сообщила Brimstone о «Project Landfall» — исследовании Interverse (альтернативной вселенной, откуда произошли радиворы).', 'video', 'video/SUNSET_treiler.mp4', 'Взрыв станции Kindom'),
(12, 5, 'Из-за этих экспериментов Brimstone усомнился в благих намерениях Kingdom. Он решил возглавить Протокол и атаковать одну из станций с порталом, вступив в столкновение с военными и учёными. Во время перестрелки портал испустил взрывную волну, от которой не пострадал только питомец Gekko (Wingman), сумевший разрушить портал. На месте разрушенного портала прибывают учёные и солдаты, однако они были ликвидированы неизвестным радиантом.', 'none', NULL, NULL),
(13, 6, 'Неизвестный радиант по имени Iso, работающий на тайную организацию, убивает всех на месте разрушенного портала. Однако присоединение к Протоколу VALORANT ставит его перед новым выбором — бороться за добро. Он намеренно оставляет улики для Cypher, чтобы тот смог его разоблачить. В это время Omen не давал покоя интерес к своему прошлому. Появление Iso дало ему некоторые зацепки, благодаря чему он начал изучать организацию «Дети песочных часов».', 'none', NULL, NULL),
(14, 6, 'Изучая библиотеку в Оренбурге, Omen встречает Clove, которая решает вступить в Протокол VALORANT и делится своим опытом: однажды «Дети песочных часов» убили её, когда она получила доступ к загадочному дневнику. Благодаря своей способности к перерождению Clove смогла выжить. Собрав необходимую информацию, Omen запрашивает у Brimstone разрешение на отправку в Джакарту, где находится штаб «Детей песочных часов». Brimstone соглашается и отправляет с Omen Iso, Cypher и Sova для выполнения этой опасной миссии. Проникнув в кабинет лидера, Omen оказывается в ловушке — в камере, подавляющей его силу. Там он вспоминает, что сам был агентом песочных часов по имени «Призрак». Его отправили убить Viper, чтобы скрыть открытие радианита, но она отбилась. Смесь её химикатов и радианита превратила его в нынешнего Omen, стерев память.', 'video', 'video/РАСПЛАТА Видеоролик к эпизоду 8.mp4', 'Воспоминания Omen'),
(15, 7, 'После инцидента Clove вспоминает, что представители организации «Дети песочных часов» упоминали: дневник необходимо доставить на указанную базу, которой является карта «Abyss». Omen, Iso и Clove направляются именно туда и устраняют всех, кто находится на объекте. В результате для Протокола VALORANT раскрывается тайна организации «Дети песочных часов»: они намеренно убивают радиантов и делают всё возможное, чтобы ограничить число людей, связанных с этим веществом.', 'video', 'video/СВЯТИЛИЩЕ ТАЙН Официальный трейлер карты Abyss.mp4', 'Штаб \"Детей песочный часов\"'),
(16, 8, 'В ходе штурма повреждаются системы безопасности, выпуская на волю Vyse (радианта, пойманного ранее). Позже Omen противостоит Viper из-за правды о своём прошлом. Затем происходит вторжение Омеги: Легион атакует несколько объектов Альфы. Спайк на Icebox взрывается, радианит похищен. Vyse охотится на агентов песочных часов, но её выслеживают в Сеуле и задерживают Jett, Chamber, Yoru и Omen, после чего она присоединяется к Протоколу. Дети песочных часов к этому моменту в основном побеждены.', 'video', 'video/ВСЕ ДОРОГИ ОКАНЧИВАЮТСЯ ЗДЕСЬ Трейлер агента Vyse.mp4', 'Первая встреча с Vyse'),
(17, 8, 'Позже Протокол получает визит от Tejo, затем присоединяются Waylay и Veto. Альфа-Killjoy погибает в Торонто, но Sage успешно воскрешает её, хотя кристаллы радианита начинают покрывать лицо Sage — первый признак того, что исцеление вредит ей.', 'video', 'video/EGO.mp4', 'Трагедия в Торонто'),
(18, 9, 'На Омеге тем временем Омега-Sage находится в вегетативном состоянии из-за перенапряжения (многократные воскрешения), а Омега-Viper свергает Омега-Brimstone и берёт полный контроль над Легионом. История продолжается столкновениями в Париже и далее, но для Протокола главное раскрытие — радианты существовали задолго до Первой Вспышки, и битва за будущее только начинается.', 'video', 'video/Season 2026 .mp4', 'Обстановка Омеги Земли');

