INSERT INTO `updates` (`id`, `title`, `description`, `video_path`, `external_link`, `badge_text`, `patch_version`) VALUES
(1, 'Miks - специалист из Хорватии', 'Miks задает настроение на поле боя, вдохновляет союзников и помогает им поддерживать нужный темп.', '/video/Teaser_Miks.mp4', 'https://www.youtube.com/watch?v=3CObqmMfjGc', 'НОВЫЙ АГЕНТ', 'Патч 12.05'),
(2, 'Облик \"Куронами 2.0\"', 'Вновь овладейте стихией бури и тени с помощью Kuronami Phantom, Operator, Guardian, Ghost и трансформирующегося куная.', '/video/Kuronami_Skin.mp4', 'https://www.youtube.com/watch?v=LbpRrH4QLFY', 'НОВАЯ КОЛЛЕКЦИЯ', 'Патч 12.08'),
(3, 'Новый VALORANT Champions Tour', 'В 2027 году VCT переходит на открытую турнирную модель: путь на Masters и Champions — через открытые квалификации для всех команд, 8 кубков в 16+ городах, призовые более $6 млн в год.', '/video/Champions.mp4', 'https://valorantesports.com/ru-RU/news/the-new-valorant-champions-tour', 'VCT 2027', NULL),
(4, 'Столкновение: возвышение', 'Появился совершенно новый способ соревноваться, и он становится более личным. Вот всё, что вам нужно знать о новом соревновательном событии 1v1 и 2v2 Столкновение: Возвышение.', '/video/Notification.mp4', 'https://www.youtube.com/watch?v=LbpRrH4QLFY', 'Новый режим', 'Патч 12.08');

